-- Opt-in, city-level location sharing and "Nearby JECians".
--
-- Privacy rules this file enforces (never trust the client):
--  * Sharing is off until the member turns it on; turning it off deletes the stored location.
--  * Coordinates are rounded to a 0.05° grid (about 5 km) here on the server BEFORE anything is stored, and the city is
--    looked up from the rounded point against a bundled city table (GeoNames, CC BY 4.0): no outside service sees them.
--  * The location tables are readable by NO client role; members only reach them through the functions below, which
--    return a city name and a distance bucket ("same city", "within 5 km", "about 40 km"), never coordinates.
--  * Only verified members who opted in appear with a distance; blocked pairs never see each other.
--  * Searches are rate-limited; the opt-in/out history is kept without any coordinates.

-- ------------------------------------------------------------------ bundled city table
create table public.geo_countries (
  code text primary key check (code ~ '^[A-Z]{2}$'),
  name text not null check (char_length(name) between 1 and 80)
);

create table public.geo_cities (
  id int primary key,                                -- GeoNames id
  name text not null check (char_length(name) between 1 and 80),
  search_key text not null,                          -- lower case, without accents
  region text,                                       -- Indian state / US state code, for telling same-named places apart
  country_code text not null references public.geo_countries (code),
  population int not null,
  lat double precision not null check (lat between -90 and 90),
  lng double precision not null check (lng between -180 and 180)
);
create index geo_cities_lat_idx on public.geo_cities (lat);
create index geo_cities_key_idx on public.geo_cities (search_key text_pattern_ops);
create index geo_cities_key_trgm_idx on public.geo_cities using gin (search_key extensions.gin_trgm_ops);

alter table public.geo_countries enable row level security;
alter table public.geo_cities enable row level security;
-- no grants: reached through search_cities() / nearby_members() only

