-- ------------------------------------------------------------------ member tables (private)
create table public.location_prefs (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  sharing boolean not null default false,
  update_profile boolean not null default false,     -- "Also update the city on my profile"
  prompt_dismissed boolean not null default false,   -- the one-time Home card
  last_set_at timestamptz,
  sets_day date,
  sets_count int not null default 0,
  updated_at timestamptz not null default now()
);

create table public.member_locations (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  -- coarse grid point (0.05°): the only position ever stored
  lat numeric(5, 2) not null check (lat between -90 and 90 and mod(lat * 100, 5) = 0),
  lng numeric(5, 2) not null check (lng between -180 and 180 and mod(lng * 100, 5) = 0),
  city_id int references public.geo_cities (id),
  city text check (char_length(city) <= 80),
  country text check (char_length(country) <= 80),
  updated_at timestamptz not null default now()
);
create index member_locations_lat_idx on public.member_locations (lat);

-- opt-in / opt-out history, never with coordinates
create table public.location_consent_log (
  id bigint generated always as identity primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  action text not null check (action in ('opt_in', 'opt_out', 'profile_city_on', 'profile_city_off')),
  created_at timestamptz not null default now()
);
create index location_consent_log_user_idx on public.location_consent_log (user_id, created_at desc);

-- rate-limit bookkeeping (timestamps only; the searched city is not recorded)
create table public.location_search_log (
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('city_search', 'suggest')),
  created_at timestamptz not null default now()
);
create index location_search_log_idx on public.location_search_log (user_id, kind, created_at desc);

alter table public.location_prefs enable row level security;
alter table public.member_locations enable row level security;
alter table public.location_consent_log enable row level security;
alter table public.location_search_log enable row level security;
-- deliberately no policies and no grants: no client role can read or write these tables directly
revoke all on public.location_prefs, public.member_locations, public.location_consent_log, public.location_search_log,
              public.geo_cities, public.geo_countries from anon, authenticated, public;

create trigger location_prefs_touch before update on public.location_prefs
  for each row execute function public.touch_updated_at();

-- ------------------------------------------------------------------ helpers (internal)
-- Snap to the 0.05° grid (about 5.5 km north-south; less east-west away from the equator).
create or replace function public._loc_round(p double precision)
returns numeric language sql immutable set search_path = '' as $$
  select round((p / 0.05)::numeric) * 0.05;
$$;

-- Great-circle distance in km.
create or replace function public._loc_km(a_lat double precision, a_lng double precision, b_lat double precision, b_lng double precision)
returns double precision language sql immutable set search_path = '' as $$
  select 2 * 6371 * asin(least(1, sqrt(
    power(sin(radians(b_lat - a_lat) / 2), 2) + cos(radians(a_lat)) * cos(radians(b_lat)) * power(sin(radians(b_lng - a_lng) / 2), 2))));
$$;

-- The city a (rounded) point belongs to. Bigger cities reach further (a suburb 15 km from Mumbai's centre is still
-- Mumbai unless a sizeable town is closer): the score is distance divided by a population-based reach
-- (about 32 km for Mumbai, 18 km for Jabalpur, 13 km for Gurgaon, 7 km for a town of 15,000).
create or replace function public._loc_nearest_city(p_lat double precision, p_lng double precision)
returns public.geo_cities language sql stable set search_path = '' as $$
  select c from (
    select c, 0 as pass, public._loc_km(p_lat, p_lng, c.lat, c.lng) / (2 + 0.5 * power(c.population, 0.25)) as score
      from public.geo_cities c
     where c.lat between p_lat - 1.5 and p_lat + 1.5
       and public._loc_km(p_lat, p_lng, c.lat, c.lng) <= 150
    union all
    select c, 1, public._loc_km(p_lat, p_lng, c.lat, c.lng) from public.geo_cities c
  ) x order by pass, score limit 1;
$$;

-- Distance shown to members: never finer than the 5 km grid.
create or replace function public._loc_approx_km(p_km double precision)
returns int language sql immutable set search_path = '' as $$
  select case when p_km < 50 then greatest(5, (round(p_km / 5) * 5)::int) else (round(p_km / 10) * 10)::int end;
$$;

revoke execute on function public._loc_round(double precision) from anon, authenticated, public;
revoke execute on function public._loc_km(double precision, double precision, double precision, double precision) from anon, authenticated, public;
revoke execute on function public._loc_nearest_city(double precision, double precision) from anon, authenticated, public;
revoke execute on function public._loc_approx_km(double precision) from anon, authenticated, public;

-- ------------------------------------------------------------------ the member's own settings
create or replace function public.my_location()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  s public.location_prefs;
  l public.member_locations;
  reg text;
begin
  if me is null then raise exception 'Please sign in again' using errcode = '42501'; end if;
  select * into s from public.location_prefs where user_id = me;
  select * into l from public.member_locations where user_id = me;
  select c.region into reg from public.geo_cities c where c.id = l.city_id;
  return jsonb_build_object(
    'sharing', coalesce(s.sharing, false),
    'update_profile', coalesce(s.update_profile, false),
    'prompt_dismissed', coalesce(s.prompt_dismissed, false),
    'city', l.city,
    'region', reg,
    'country', l.country,
    -- the member's own coarse grid point (about 5 km), for their own data download; never shown for anyone else
    'lat', l.lat,
    'lng', l.lng,
    'updated_at', l.updated_at,
    'history', coalesce((select jsonb_agg(jsonb_build_object('action', h.action, 'at', h.created_at) order by h.id desc)
                           from (select * from public.location_consent_log where user_id = me order by id desc limit 50) h), '[]'::jsonb));
end;
$$;

-- Turn sharing on (or off). Turning off deletes the stored location.
create or replace function public.set_location_sharing(p_on boolean, p_update_profile boolean default false)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  old public.location_prefs;
begin
  if me is null then raise exception 'Please sign in again' using errcode = '42501'; end if;
  if not coalesce(p_on, false) then return public.clear_my_location(); end if;
  select * into old from public.location_prefs where user_id = me;
  insert into public.location_prefs (user_id, sharing, update_profile, prompt_dismissed)
  values (me, true, coalesce(p_update_profile, false), true)
  on conflict (user_id) do update set sharing = true, update_profile = coalesce(p_update_profile, false), prompt_dismissed = true;
  if not coalesce(old.sharing, false) then
    insert into public.location_consent_log (user_id, action) values (me, 'opt_in');
  end if;
  if coalesce(old.update_profile, false) is distinct from coalesce(p_update_profile, false) then
    insert into public.location_consent_log (user_id, action)
    values (me, case when p_update_profile then 'profile_city_on' else 'profile_city_off' end);
  end if;
  return public.my_location();
end;
$$;

create or replace function public.clear_my_location()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  was boolean;
begin
  if me is null then raise exception 'Please sign in again' using errcode = '42501'; end if;
  select sharing into was from public.location_prefs where user_id = me;
  delete from public.member_locations where user_id = me;
  insert into public.location_prefs (user_id, sharing, update_profile, prompt_dismissed)
  values (me, false, false, true)
  on conflict (user_id) do update set sharing = false, update_profile = false, prompt_dismissed = true;
  if coalesce(was, false) then
    insert into public.location_consent_log (user_id, action) values (me, 'opt_out');
  end if;
  return public.my_location();
end;
$$;

-- "No thanks" on the Home card: never ask again.
create or replace function public.dismiss_location_prompt()
returns void language sql security definer set search_path = '' as $$
  insert into public.location_prefs (user_id, prompt_dismissed) select auth.uid(), true where auth.uid() is not null
  on conflict (user_id) do update set prompt_dismissed = true;
$$;

-- Store the member's approximate position (opt-in required). Rounded and turned into a city here.
create or replace function public.set_my_location(p_lat double precision, p_lng double precision)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  s public.location_prefs;
  has_row boolean;
  rlat numeric;
  rlng numeric;
  c public.geo_cities;
  cname text;
begin
  if me is null then raise exception 'Please sign in again' using errcode = '42501'; end if;
  if p_lat is null or p_lng is null or p_lat = 'NaN'::float8 or p_lng = 'NaN'::float8
     or p_lat not between -90 and 90 or p_lng not between -180 and 180 then
    raise exception 'That location doesn’t look right' using hint = 'loc.errBadPoint';
  end if;
  select * into s from public.location_prefs where user_id = me for update;
  if not coalesce(s.sharing, false) then
    raise exception 'Turn on “Share my city” first' using hint = 'loc.errNotSharing';
  end if;
  has_row := exists (select 1 from public.member_locations where user_id = me);
  -- at most one update every 10 minutes, and 20 a day in all (re-enabling sharing included)
  if has_row and s.last_set_at > now() - interval '10 minutes' then
    raise exception 'Your city was updated a few minutes ago. Please try again later.' using hint = 'loc.errTooSoon';
  end if;
  if s.sets_day = current_date and s.sets_count >= 20 then
    raise exception 'Your city was updated many times today. Please try again tomorrow.' using hint = 'loc.errDaily';
  end if;

  rlat := public._loc_round(p_lat);
  rlng := public._loc_round(p_lng);
  if rlng > 180 then rlng := 180; end if;
  if rlng < -180 then rlng := -180; end if;
  c := public._loc_nearest_city(rlat::float8, rlng::float8);
  select coalesce(gc.name, c.country_code) into cname from public.geo_countries gc where gc.code = c.country_code;

  insert into public.member_locations (user_id, lat, lng, city_id, city, country, updated_at)
  values (me, rlat, rlng, c.id, c.name, cname, now())
  on conflict (user_id) do update set lat = excluded.lat, lng = excluded.lng, city_id = excluded.city_id,
    city = excluded.city, country = excluded.country, updated_at = now();
  update public.location_prefs
     set last_set_at = now(),
         sets_day = current_date,
         sets_count = case when sets_day = current_date then sets_count + 1 else 1 end
   where user_id = me;
  if s.update_profile and c.name is not null then
    update public.profiles set city = c.name, country = cname
     where id = me and (city is distinct from c.name or country is distinct from cname);
  end if;
  return public.my_location();
end;
$$;

-- ------------------------------------------------------------------ rate limit
create or replace function public._loc_rate(p_kind text, p_max int, p_window interval)
returns void language plpgsql security definer set search_path = '' as $$
declare n int;
begin
  delete from public.location_search_log where user_id = auth.uid() and created_at < now() - interval '1 day';
  select count(*) into n from public.location_search_log
   where user_id = auth.uid() and kind = p_kind and created_at > now() - p_window;
  if n >= p_max then
    raise exception 'Too many searches. Please wait a few minutes and try again.' using hint = 'loc.errSearchRate';
  end if;
  insert into public.location_search_log (user_id, kind) values (auth.uid(), p_kind);
end;
$$;
revoke execute on function public._loc_rate(text, int, interval) from anon, authenticated, public;

-- ------------------------------------------------------------------ city suggestions
create or replace function public.search_cities(p_query text, p_limit int default 8)
returns table (id int, name text, region text, country text, population int)
language plpgsql security definer set search_path = '' as $$
declare
  q text := lower(btrim(coalesce(p_query, '')));
begin
  if not public.is_verified() then raise exception 'Only verified members can search' using errcode = '42501'; end if;
  if char_length(q) < 2 then return; end if;
  q := left(q, 60);
  perform public._loc_rate('suggest', 300, interval '10 minutes');
  return query
    select c.id, c.name, c.region, coalesce(gc.name, c.country_code), c.population
      from public.geo_cities c
      left join public.geo_countries gc on gc.code = c.country_code
     where c.search_key like replace(replace(q, '%', ''), '_', '\_') || '%'
        or c.search_key like '% ' || replace(replace(q, '%', ''), '_', '\_') || '%'
        or (char_length(q) >= 4 and c.search_key operator(extensions.%) q)
     order by (c.search_key = q) desc, (c.search_key like replace(replace(q, '%', ''), '_', '\_') || '%') desc,
              (c.country_code = 'IN') desc, c.population desc
     limit least(greatest(coalesce(p_limit, 8), 1), 20);
end;
$$;

-- ------------------------------------------------------------------ Nearby JECians
-- Origin: the caller's own (shared) location, or the centre of a city they search for ("I'm travelling to Pune").
-- Rows: verified, onboarded members who opted in (with an approximate distance), plus, for the origin city, members
-- whose profile says they live there (labelled "from profile", no distance). Never coordinates.
--   bucket: same_city | within_5 | km (see approx_km) | profile
create or replace function public.nearby_members(
  p_city_id int default null,
  p_scope text default 'all',          -- all | batch | branch
  p_year_from int default null,
  p_year_to int default null,
  p_query text default null,           -- profession / company / name
  p_mentors boolean default false,
  p_helpers boolean default false,
  p_radius_km int default 100,
  p_limit int default 100
)
returns table (user_id uuid, full_name text, avatar_url text, grad_year int, branch text, headline text, current_title text,
               current_company text, city text, country text, cluster_id int, cluster_name text, cluster_lat double precision,
               cluster_lng double precision, source text, bucket text, approx_km int, same_batch boolean, is_mentor boolean,
               can_help boolean)
language plpgsql security definer set search_path = '' as $$
#variable_conflict use_column
declare
  me uuid := auth.uid();
  my public.profiles;
  o_lat double precision;
  o_lng double precision;
  o_city text;
  o_key text;
  o_country text;
  o_city_id int;
  radius int := least(greatest(coalesce(p_radius_km, 100), 5), 200);
  q text := nullif(btrim(coalesce(p_query, '')), '');
  c public.geo_cities;
  l public.member_locations;
begin
  if not public.is_verified() then raise exception 'Only verified members can see who is nearby' using errcode = '42501'; end if;
  if coalesce(p_scope, 'all') not in ('all', 'batch', 'branch') then raise exception 'Unknown filter'; end if;
  select * into my from public.profiles where id = me;
  if q is not null then q := '%' || replace(replace(replace(left(q, 80), '\', '\\'), '%', '\%'), '_', '\_') || '%'; end if;

  if p_city_id is null then
    select m.* into l from public.member_locations m join public.location_prefs s on s.user_id = m.user_id and s.sharing
     where m.user_id = me;
    if not found then
      raise exception 'Turn on city sharing to see who’s near you' using hint = 'loc.errNotSharing';
    end if;
    o_lat := l.lat; o_lng := l.lng; o_city := l.city; o_country := l.country; o_city_id := l.city_id;
    select gc.search_key into o_key from public.geo_cities gc where gc.id = l.city_id;
  else
    perform public._loc_rate('city_search', 30, interval '10 minutes');
    select * into c from public.geo_cities where id = p_city_id;
    if not found then raise exception 'City not found'; end if;
    o_lat := c.lat; o_lng := c.lng; o_city := c.name; o_key := c.search_key; o_city_id := c.id;
    select coalesce(gc.name, c.country_code) into o_country from public.geo_countries gc where gc.code = c.country_code;
  end if;

  return query
  select x.* from (
  with people as (
    select p.*,
           exists (select 1 from public.mentor_profiles mp where mp.user_id = p.id and mp.is_accepting) as mentor,
           cardinality(p.help_tags) > 0 as helper
      from public.profiles p
     where p.id <> me and p.onboarded and p.verification = 'verified'
       and not public.is_blocked_between(p.id, me)
       and (coalesce(p_scope, 'all') <> 'batch' or (my.grad_year is not null and p.grad_year = my.grad_year))
       and (coalesce(p_scope, 'all') <> 'branch' or (my.branch is not null and p.branch = my.branch))
       and (p_year_from is null or p.grad_year >= p_year_from)
       and (p_year_to is null or p.grad_year <= p_year_to)
       and (q is null or concat_ws(' ', p.full_name, p.headline, p.current_title, p.current_company) ilike q)
  ),
  live as (
    select p.id, m.city, m.country, m.city_id, public._loc_km(o_lat, o_lng, m.lat::float8, m.lng::float8) as d,
           (m.city_id = o_city_id or (lower(m.city) = lower(o_city) and m.country = o_country)) as same_city
      from people p
      join public.member_locations m on m.user_id = p.id
      join public.location_prefs s on s.user_id = p.id and s.sharing
  ),
  live_in as (select * from live where d <= radius or same_city),
  from_profile as (
    select p.id from people p
     where lower(btrim(p.city)) in (lower(o_city), o_key)
       and coalesce(nullif(btrim(p.country), ''), 'India') = o_country
       and not exists (select 1 from live_in li where li.id = p.id)
  )
  select p.id, p.full_name as r_name, p.avatar_url, p.grad_year, p.branch, p.headline, p.current_title, p.current_company,
         li.city, li.country, gc.id, gc.name, gc.lat, gc.lng, 'live'::text as r_source,
         case when li.same_city then 'same_city' when li.d < 5 then 'within_5' else 'km' end as r_bucket,
         case when li.same_city or li.d < 5 then null else public._loc_approx_km(li.d) end as r_km,
         (my.grad_year is not null and p.grad_year = my.grad_year) as r_batch, p.mentor, p.helper
    from live_in li
    join people p on p.id = li.id
    left join public.geo_cities gc on gc.id = li.city_id
   where (not p_mentors or p.mentor) and (not p_helpers or p.helper)
  union all
  select p.id, p.full_name, p.avatar_url, p.grad_year, p.branch, p.headline, p.current_title, p.current_company,
         p.city, coalesce(nullif(btrim(p.country), ''), 'India'), o_city_id, o_city,
         (select g.lat from public.geo_cities g where g.id = o_city_id), (select g.lng from public.geo_cities g where g.id = o_city_id),
         'profile', 'profile', null::int,
         (my.grad_year is not null and p.grad_year = my.grad_year), p.mentor, p.helper
    from from_profile fp
    join people p on p.id = fp.id
   where (not p_mentors or p.mentor) and (not p_helpers or p.helper)
  ) x
  order by x.r_source, case x.r_bucket when 'same_city' then 0 when 'within_5' then 1 else 2 end, x.r_km nulls first,
           x.r_batch desc, x.r_name
  limit least(greatest(coalesce(p_limit, 100), 1), 200);
end;
$$;

-- The simple, future-ready version for "batchmates near you" alerts: opted-in members only, city + bucket only.
create or replace function public.batchmates_nearby(p_radius_km int default 100)
returns table (user_id uuid, full_name text, avatar_url text, grad_year int, branch text, city text, country text,
               bucket text, same_batch boolean)
language sql security definer set search_path = '' as $$
  select n.user_id, n.full_name, n.avatar_url, n.grad_year, n.branch, n.city, n.country,
         case when n.bucket in ('same_city') then 'same_city'
              when n.bucket = 'within_5' or n.approx_km <= 25 then 'within_25'
              else 'within_100' end,
         n.same_batch
    from public.nearby_members(null, 'all', null, null, null, false, false, least(greatest(coalesce(p_radius_km, 100), 5), 100), 200) n
   where n.source = 'live'
   order by n.same_batch desc, (n.bucket = 'same_city') desc, n.approx_km nulls first, n.full_name;
$$;

-- ------------------------------------------------------------------ grants
revoke execute on function public.my_location() from anon, public;
revoke execute on function public.set_location_sharing(boolean, boolean) from anon, public;
revoke execute on function public.clear_my_location() from anon, public;
revoke execute on function public.dismiss_location_prompt() from anon, public;
revoke execute on function public.set_my_location(double precision, double precision) from anon, public;
revoke execute on function public.search_cities(text, int) from anon, public;
revoke execute on function public.nearby_members(int, text, int, int, text, boolean, boolean, int, int) from anon, public;
revoke execute on function public.batchmates_nearby(int) from anon, public;
grant execute on function public.my_location() to authenticated;
grant execute on function public.set_location_sharing(boolean, boolean) to authenticated;
grant execute on function public.clear_my_location() to authenticated;
grant execute on function public.dismiss_location_prompt() to authenticated;
grant execute on function public.set_my_location(double precision, double precision) to authenticated;
grant execute on function public.search_cities(text, int) to authenticated;
grant execute on function public.nearby_members(int, text, int, int, text, boolean, boolean, int, int) to authenticated;
grant execute on function public.batchmates_nearby(int) to authenticated;
